item.command:
/bin/zsh -lc "cat > answer.json <<'EOF'
{
  \"owner_file\": \"src/billing/receipt.js\",
  \"owner_symbol\": \"makeReceiptKey\",
  \"outbound_file\": \"src/transport/invoices.js\",
  \"outbound_symbol\": \"sendInvoice\",
  \"call_chain\": [
    \"src/app.js:checkout\",
    \"src/billing/submit.js:submitInvoice\",
    \"src/billing/receipt.js:makeReceiptKey\",
    \"src/transport/invoices.js:sendInvoice\"
  ],
  \"example_key\": \"invoice/acme/0007\"
}
EOF
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { checkout } from './src/app.js';
import { makeReceiptKey as billingKey } from './src/billing/receipt.js';
import { makeReceiptKey as reportKey } from './src/reports/receipt.js';
import { makeReceiptKey as transportKey } from './src/transport/receipt.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['owner_file', 'owner_symbol', 'outbound_file', 'outbound_symbol', 'call_chain', 'example_key']);
assert.equal(answer.owner_file, 'src/billing/receipt.js');
assert.equal(answer.owner_symbol, 'makeReceiptKey');
assert.equal(answer.outbound_file, 'src/transport/invoices.js');
assert.equal(answer.outbound_symbol, 'sendInvoice');
assert.deepEqual(answer.call_chain, ['src/app.js:checkout', 'src/billing/submit.js:submitInvoice', 'src/billing/receipt.js:makeReceiptKey', 'src/transport/invoices.js:sendInvoice']);
const invoice = { accountId: 'acme', sequence: 7 };
assert.equal(billingKey(invoice), answer.example_key);
let request;
await checkout(invoice, { post(...args) { request = args; return 'ok'; } });
assert.deepEqual(request, ['/invoices', invoice, { 'Idempotency-Key': answer.example_key }]);
assert.equal(reportKey({ id: 'acme' }), 'report:acme');
assert.equal(transportKey({ headers: { 'x-receipt': 'receipt-value' } }), 'receipt-value');
console.log('PASS: answer.json schema and checkout-to-header example verified; receipt helpers distinguished.');
EOF"

